{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.berrylush_warehouse_sla_performance AS WITH unicom AS ( SELECT awb, MARKETPLACE, marketplace_mapped, shippingpackagecode, order_id, order_name, SELLING_PRICE, saleorderitemcode, sku, order_status, order_date, order_timestamp, SHIPPING_LAST_UPDATE_TIMESTAMP, shipping_courier, warehouse_name, shipping_status, ON_HOLD, CASE WHEN SALE_ORDER_ITEM_STATUS = \'PICKING_FOR_INVOICING\' THEN shippingpackagestatus ELSE SALE_ORDER_ITEM_STATUS END AS UC_STATUS, dispatched_timestamp AS \"UC_Dispatched\", dispatch_date, delivered_date, item_details, address_line_1, uc_created, CASE WHEN upper(MARKETPLACE) = \'SHOPIFY\' THEN CASE WHEN uc_created::DATE in (\'2025-11-26\',\'2025-11-27\',\'2025-11-28\',\'2025-11-29\',\'2025-11-30\',\'2025-12-01\',\'2025-12-02\') THEN DATEADD(HOUR, 12, uc_created::timestamp) WHEN order_date > \'2024-09-20\' THEN CASE WHEN upper(warehouse_name) = \'SAPL-WH2\' THEN CASE WHEN order_date >= \'2026-06-17\' AND (EXTRACT(HOUR FROM uc_created)) = 0 AND (EXTRACT(MINUTE FROM uc_created)) <= 0 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'120 minutes\' WHEN (EXTRACT(HOUR FROM uc_created)) < 3 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'5 hours\' WHEN order_date >= \'2026-05-04\' AND (EXTRACT(HOUR FROM uc_created)) >= 3 AND ( (EXTRACT(HOUR FROM uc_created)) < 12 OR ((EXTRACT(HOUR FROM uc_created)) = 12 AND (EXTRACT(MINUTE FROM uc_created)) <= 30) ) THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'14 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 3 AND (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN order_date >= \'2026-06-17\' AND (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'120 minutes\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'5 hours\' ELSE fulfillment_tat END WHEN upper(warehouse_name) = \'SAPL-WH1\' and order_date >= \'2025-05-20\' THEN CASE WHEN order_date >= \'2026-06-17\' AND (EXTRACT(HOUR FROM uc_created)) = 0 AND (EXTRACT(MINUTE FROM uc_created)) <= 0 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'120 minutes\' WHEN (EXTRACT(HOUR FROM uc_created)) < 3 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'5 hours\' WHEN order_date >= \'2026-05-04\' AND (EXTRACT(HOUR FROM uc_created)) >= 3 AND ( (EXTRACT(HOUR FROM uc_created)) < 12 OR ((EXTRACT(HOUR FROM uc_created)) = 12 AND (EXTRACT(MINUTE FROM uc_created)) <= 30) ) THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'14 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 3 AND (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN order_date >= \'2026-06-17\' AND (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'120 minutes\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'5 hours\' ELSE fulfillment_tat END WHEN upper(warehouse_name) = \'SAPL_EMIZA\' and order_Date >= \'2025-04-01\' THEN CASE WHEN (EXTRACT(HOUR FROM uc_created)) < 4 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'6 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 4 AND (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'6 hours\' ELSE fulfillment_tat END WHEN upper(warehouse_name) = \'SAPL-NORTH-TAURU\' and order_Date >= \'2025-11-20\' THEN CASE WHEN order_date >= \'2026-06-17\' AND (EXTRACT(HOUR FROM uc_created)) = 0 AND (EXTRACT(MINUTE FROM uc_created)) <= 0 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'120 minutes\' WHEN (EXTRACT(HOUR FROM uc_created)) < 4 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'6 hours\' WHEN order_date >= \'2026-05-04\' AND (EXTRACT(HOUR FROM uc_created)) >= 4 AND ( (EXTRACT(HOUR FROM uc_created)) < 12 OR ((EXTRACT(HOUR FROM uc_created)) = 12 AND (EXTRACT(MINUTE FROM uc_created)) <= 30) ) THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'14 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 4 AND (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN order_date >= \'2026-06-17\' AND (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'120 minutes\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'6 hours\' ELSE fulfillment_tat END ELSE CASE WHEN (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'18 hours\' ELSE fulfillment_tat END END ELSE CASE WHEN (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'18 hours\' ELSE fulfillment_tat END END ELSE fulfillment_tat END AS TAT, category, SHIPPING_PACKAGE_TYPE, REVERSE_PICKUP_CODE, REVERSE_PICKUP_CREATED, NOTIFICATION_EMAIL, NOTIFICATION_MOBILE, CUSTOMIZATION, DISCOUNT_CODE, COD, SHIPPING_ID, CANCELLATION_REASON, SHIPPING_ARRANGED_BY, PACKAGE_LENGTH, PACKAGE_WIDTH, PACKAGE_HEIGHT, RETURN_DATE, RETURN_REASON, RETURN_REMARKS, ITEM_CODE, weight, SKU_NAME, SHIPPING_COURIER_STATUS, SHIPPING_TRACKING_STATUS, PACKED_TIME, PACKING_USER, ITEM_FINAL_STATUS, order_type, store_code, saleinvoiceprefix, ORDER_AMOUNT FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 where order_Date >= current_date - 60 and warehouse_name = \'Berrylushbrands_SR\' ), forward AS ( SELECT \"Shipping Package Code\", created_timestamp, picking_timestamp, picked_timestamp, packed_timestamp, rts_timestamp, manifested_timestamp, dispatched_timestamp AS dispatched_timestamp1, shipped_timestamp, delivered_timestamp, cancelled_timestamp, \"created&dispatch\", \"pick&dispatch\", \"pack&dispatch\", LATEST_STATUS, LAST_UPDATED FROM snitch_db.maplemonk.forward_timestamps ), clickpost AS ( SELECT awb, \"Order Date\" AS CP_orderplaced, \"Pickup Date\", \"Delivery Date\" AS CP_Delivery, \"Clickpost Unified Status\" as CP_STATUS FROM snitch_db.maplemonk.snitch_clickpost_track_order_dashboard_report ), sr AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_SR ), wh AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_WH ), wh2 AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_WH2 ), emiza AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_EMIZA ), marketplace AS ( (SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_MARKET_PLACE_ERROR_ORDERS ) UNION ALL (select \"Order ID\", warehouse from snitch_db.maplemonk.gs_mp_error_north) ), unicom_error AS ( SELECT u.*, CASE WHEN u.marketplace_mapped = \'SHOPIFY\' THEN CASE WHEN u.warehouse_name = \'SAPL_EMIZA\' AND EXISTS (SELECT 1 FROM emiza WHERE emiza.\"Order ID\" = u.order_name AND emiza.warehouse = \'SAPL_EMIZA\') THEN 1 WHEN u.warehouse_name = \'SAPL-WH1\' AND EXISTS (SELECT 1 FROM wh WHERE wh.\"Order ID\" = u.order_name AND wh.warehouse = \'SAPL-WH1\') THEN 1 WHEN u.warehouse_name = \'SAPL-NORTH-TAURU\' AND EXISTS (SELECT 1 FROM sr WHERE sr.\"Order ID\" = u.order_name AND sr.warehouse = \'SAPL-NORTH-TAURU\') THEN 1 WHEN u.warehouse_name = \'SAPL-WH2\' AND EXISTS (SELECT 1 FROM wh2 WHERE wh2.\"Order ID\" = u.order_name AND wh2.warehouse = \'SAPL-WH2\') THEN 1 ELSE NULL END WHEN u.marketplace_mapped NOT IN (\'SHOPIFY\', \'OWN_STORE\', \'FRANCHISE_STORE\') THEN CASE WHEN EXISTS (SELECT 1 FROM marketplace WHERE marketplace.\"Order ID\" = u.order_name AND marketplace.warehouse = u.warehouse_name) THEN 1 ELSE NULL END ELSE NULL END AS ERROR FROM unicom u ), main_data AS ( SELECT ue.*, f.created_timestamp, f.picking_timestamp, f.picked_timestamp, f.packed_timestamp, f.rts_timestamp, f.manifested_timestamp, f.dispatched_timestamp1, f.shipped_timestamp, f.delivered_timestamp, f.cancelled_timestamp, f.\"created&dispatch\", f.\"pick&dispatch\", f.\"pack&dispatch\", f.LATEST_STATUS, f.LAST_UPDATED, cp.CP_orderplaced, cp.\"Pickup Date\", cp.CP_Delivery, cp.CP_STATUS FROM unicom_error ue LEFT JOIN forward f ON ue.shippingpackagecode = f.\"Shipping Package Code\" LEFT JOIN clickpost cp ON ue.awb = cp.awb ), over AS ( SELECT don, soic, facwarehouse, overrulestatus FROM snitch_db.maplemonk.gs_overrule ), mast1 AS ( SELECT md.*, ov.* FROM main_data md LEFT JOIN over ov ON md.saleorderitemcode = ov.soic ), new_status AS ( SELECT m1.*, CASE when overrulestatus = \'DISPATCHED\' THEN created_timestamp END AS dispatchedtimestamp1, COALESCE(COALESCE(dispatchedtimestamp1,dispatched_timestamp1),\"UC_Dispatched\") AS dispatched_timestamp, CASE WHEN last_updated > SHIPPING_LAST_UPDATE_TIMESTAMP THEN LATEST_STATUS ELSE UC_STATUS END AS ITEM_STATUS1, coalesce (overrulestatus,ITEM_STATUS1) as ITEM_STATUS, CASE WHEN ITEM_STATUS = \'CANCELLED\' THEN CASE WHEN dispatched_timestamp IS NULL THEN \'CANCELLED\' ELSE CASE WHEN dispatched_timestamp <= TAT THEN \'WITHIN SLA\' ELSE \'BREACHED\' END END WHEN TAT > CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', GETDATE()) AND ITEM_STATUS IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURNED\') THEN \'FUTURE DATE-COMPLETED\' WHEN TAT > CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', GETDATE()) AND ITEM_STATUS NOT IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURNED\') THEN \'FUTURE DATE-PENDING\' ELSE CASE WHEN ITEM_STATUS IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURN_EXPECTED\') THEN CASE WHEN dispatched_timestamp <= TAT THEN \'WITHIN SLA\' ELSE \'BREACHED\' END WHEN ITEM_STATUS IN (\'CREATED\', \'MANIFESTED\', \'PICKING\', \'PICKED\', \'PACKED\', \'READY_TO_SHIP\', \'PICKING_FOR_INVOICING\', \'FULFILLABLE\') THEN \'BREACHED - PENDING FOR PROCESS\' WHEN ITEM_STATUS = \'UNFULFILLABLE\' THEN \'UNFULFILLABLE\' ELSE \'BREACHED\' END END AS SLA_Status, CASE WHEN marketplace_mapped = \'MYNTRA\' THEN CASE WHEN LOWER(SLA_Status) = \'cancelled\' THEN \'CANCELLED\' WHEN LOWER(SLA_Status) NOT IN ( \'cancelled\', \'within sla\', \'breached\', \'future date-completed\' ) THEN \'PENDING\' ELSE CASE WHEN category IN ( \'Accessories\', \'Sunglass\', \'Shorts\', \'Pyjama\', \'Boxer\', \'Co-ords\', \'Jogsuit\', \'Underpants\' ) AND COALESCE(item_details, \'\') = \'\' THEN \'CORRECT\' WHEN LOWER(item_details) LIKE \'%mp%\' THEN \'CORRECT\' ELSE \'INCORRECT\' END END WHEN marketplace_mapped = \'FLIPKART\' THEN CASE WHEN LOWER(SLA_Status) = \'cancelled\' THEN \'CANCELLED\' WHEN LOWER(SLA_Status) NOT IN ( \'cancelled\', \'within sla\', \'breached\', \'future date-completed\' ) THEN \'PENDING\' ELSE CASE WHEN category IN ( \'Accessories\', \'Bags\', \'Belts\', \'Footwear\', \'Perfumes\', \'Shoes\', \'Sunglass\', \'Sunglasses\' ) AND COALESCE(item_details, \'\') = \'\' THEN \'CORRECT\' WHEN LOWER(item_details) LIKE \'%y%\' THEN \'CORRECT\' ELSE \'INCORRECT\' END END WHEN marketplace_mapped IN (\'NYKAA_FASHION\') THEN CASE WHEN LOWER(SLA_Status) = \'cancelled\' THEN \'CANCELLED\' WHEN LOWER(SLA_Status) NOT IN ( \'cancelled\', \'within sla\', \'breached\', \'future date-completed\' ) THEN \'PENDING\' ELSE CASE WHEN category IN ( \'Accessories\', \'Bags\', \'Belts\', \'Footwear\', \'Perfumes\', \'Shoes\', \'Sunglass\', \'Sunglasses\' ) AND COALESCE(item_details, \'\') = \'\' THEN \'CORRECT\' WHEN LOWER(item_details) LIKE \'%n%\' THEN \'CORRECT\' WHEN LOWER(item_details) LIKE \'%mp%\' THEN \'CORRECT\' ELSE \'INCORRECT\' END END ELSE \'OTHER CHANNEL\' END AS Myntra_Tag_Loops, CASE WHEN marketplace_mapped like \'%AJIO%\' THEN \'MP_Shift_TAT\' WHEN marketplace_mapped = \'SHOPIFY\' AND EXTRACT(HOUR FROM TAT) = 2 THEN \'Midnight_TAT\' WHEN EXTRACT(HOUR FROM TAT) < 7 THEN \'Night_Shift_TAT\' WHEN EXTRACT(HOUR FROM TAT) = 14 THEN \'Noon_Shift_TAT\' WHEN EXTRACT(HOUR FROM TAT) = 18 THEN \'Day_Shift_TAT\' ELSE \'MP_SHIFT_TAT\' END AS tat_type , CASE WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 0 THEN \'D0\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 1 THEN \'D1\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 2 THEN \'D2\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 3 THEN \'D3\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 3 AND TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) <= 5 THEN \'D>3\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 5 AND TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) <= 7 THEN \'D>5\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 7 AND TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) <= 9 THEN \'D>7\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 9 THEN \'D>9\' END AS Ageing, case when dispatched_timestamp IS NOT NULL AND ((\"Pickup Date\" IS NULL) OR (\"Pickup Date\" = \'\')) AND awb IS NOT NULL AND marketplace_mapped = \'SHOPIFY\' AND cp_status not in (\'Cancelled\',\'RTO-Delivered\') THEN \'Handover_Pending\' ELSE \'NA\' END AS handover_status, CASE WHEN dispatched_timestamp IS NOT NULL AND ((\"Pickup Date\" IS NULL) OR (\"Pickup Date\" = \'\')) AND awb IS NOT NULL AND marketplace_mapped = \'SHOPIFY\' THEN CASE WHEN TIMESTAMPDIFF(HOUR, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) < 12 THEN \'<12H\' WHEN TIMESTAMPDIFF(HOUR, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 12 AND 24 THEN \'1D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 1 THEN \'2D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 2 AND 5 THEN \'5D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 5 AND 10 THEN \'10D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 10 AND 30 THEN \'30D\' ELSE \'30D+\' END ELSE \'NA\' END as handover_ageing FROM mast1 m1 ), final123 as (select n.*, case when e.saleorderitemcode is not null then 1 else null end as exchange_flag from new_status n left join snitch_db.maplemonk.SF_EXCHANGE_WH_STORING e on n.saleorderitemcode = e.saleorderitemcode), save_rows as (SELECT * FROM final123 WHERE warehouse_name = \'Berrylushbrands_SR\'), switch as ( select order_name, saleorderitemcode, warehouse_name, new_facility, switch_flag as sf from snitch_db.maplemonk.switch_storing ) select w.* , s.sf, coalesce(exchange_flag,s.sf,error) as delay_flag from save_rows w left join switch s on w.saleorderitemcode = s.saleorderitemcode ; CREATE OR REPLACE TABLE snitch_db.maplemonk.berrylush_final_inventory AS SELECT TO_VARIANT(TRY_TO_NUMBER(\"Bad Inventory\")) AS \"Bad Inventory\", brand AS \"BRAND\", \"Category Name\", color AS \"COLOR\", TO_VARIANT(TRY_TO_NUMBER(\"Cost Price\")) AS \"Cost Price\", ean AS \"EAN\", TO_VARIANT(TRY_TO_BOOLEAN(enabled)) AS \"ENABLED\", facility AS \"FACILITY\", NULL AS \"GRN Price With Tax\", NULL AS \"GRN Price Without Tax\", isbn AS \"ISBN\", TO_VARIANT(TRY_TO_NUMBER(inventory)) AS \"INVENTORY\", TO_VARIANT(TRY_TO_NUMBER(\"Inventory Blocked\")) AS \"Inventory Blocked\", TO_VARIANT(TRY_TO_NUMBER(\"Inventory Not Synced\")) AS \"Inventory Not Synced\", \"Item SkuCode\", \"Item Type Name\", TO_VARIANT(TRY_TO_NUMBER(mrp)) AS \"MRP\", \"Not Found\", TO_VARIANT(TRY_TO_NUMBER(\"Open Purchase\")) AS \"Open Purchase\", TO_VARIANT(TRY_TO_NUMBER(\"Open Sale\")) AS \"Open Sale\", TO_VARIANT(TRY_TO_NUMBER(\"Pending Inventory Assessment\")) AS \"Pending Inventory Assessment\", TO_VARIANT(TRY_TO_NUMBER(\"Putaway Pending\")) AS \"Putaway Pending\", TO_VARIANT(TRY_TO_NUMBER(\"Putback Pending\")) AS \"Putback Pending\", size AS \"SIZE\", TO_VARIANT(TRY_TO_NUMBER(\"Stock In Transfer\")) AS \"Stock In Transfer\", upc AS \"UPC\", updated AS \"UPDATED\", NULL AS \"_AIRBYTE_EMITTED_AT\", current_date::DATE AS \"DATE\", 1 AS \"RW\" FROM snitch_db.maplemonk.unicommerce_get_inventory_snapshot_not_found WHERE facility = \'Berrylushbrands_SR\' AND \"Category Name\" NOT IN (\'NON- TRADING\',\'CARRY BAG\') ; CREATE OR REPLACE TABLE snitch_db.maplemonk.berrylush_b2c_ns_daily AS WITH params AS ( SELECT CAST(CONVERT_TIMEZONE(\'America/Los_Angeles\',\'Asia/Kolkata\', CURRENT_TIMESTAMP) AS DATE) AS IST_TODAY ), base AS ( SELECT CAST(TAT AS DATE) AS REPORT_DATE, UPPER(TRIM(WAREHOUSE_NAME)) AS WAREHOUSE_NAME, UPPER(TRIM(MARKETPLACE_MAPPED)) AS MARKETPLACE_MAPPED, UPPER(TRIM(SLA_STATUS)) AS SLA_STATUS, LOWER(IFNULL(CANCELLATION_REASON,\'\')) AS CANCELLATION_REASON, SALEORDERITEMCODE, ORDER_TIMESTAMP, UC_CREATED, DISPATCHED_TIMESTAMP, PACKED_TIME FROM snitch_db.maplemonk.berrylush_warehouse_sla_performance WHERE UPPER(IFNULL(WAREHOUSE_NAME,\'\')) IN (\'BERRYLUSHBRANDS_SR\') AND UPPER(IFNULL(MARKETPLACE_MAPPED,\'\')) IN ( \'SHOPIFY\',\'AMAZON\',\'FLIPKART\',\'MYNTRA\',\'AJIO\',\'NYKAA.COM\',\'NYKAA_FASHION\',\'POPCLUB\' ) AND EXCHANGE_FLAG IS NULL AND ERROR IS NULL ), daily AS ( SELECT REPORT_DATE, COUNT(DISTINCT SALEORDERITEMCODE) AS FORWARD_ITEMS, COUNT(DISTINCT CASE WHEN NOT (CANCELLATION_REASON LIKE ANY (\'%cust%\',\'%sell%\',\'%cx%\',\'%other%\',\'%panel%\',\'%test%\',\'%mer%\')) THEN SALEORDERITEMCODE END ) AS FULFILL_NUM, COUNT(DISTINCT SALEORDERITEMCODE) AS FULFILL_DEN, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND SLA_STATUS = \'WITHIN SLA\' THEN SALEORDERITEMCODE END ) AS SLA_SF_NUM, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND SLA_STATUS <> \'CANCELLED\' THEN SALEORDERITEMCODE END ) AS SLA_SF_DEN, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED IN (\'AMAZON\',\'FLIPKART\',\'MYNTRA\',\'AJIO\',\'NYKAA.COM\',\'NYKAA_FASHION\',\'POPCLUB\') AND SLA_STATUS = \'WITHIN SLA\' THEN SALEORDERITEMCODE END ) AS SLA_MP_NUM, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED IN (\'AMAZON\',\'FLIPKART\',\'MYNTRA\',\'AJIO\',\'NYKAA.COM\',\'NYKAA_FASHION\',\'POPCLUB\') AND SLA_STATUS <> \'CANCELLED\' THEN SALEORDERITEMCODE END ) AS SLA_MP_DEN, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND ORDER_TIMESTAMP IS NOT NULL AND DISPATCHED_TIMESTAMP IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, DISPATCHED_TIMESTAMP) END) AS O2M_OVERALL, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH1\' AND ORDER_TIMESTAMP IS NOT NULL AND DISPATCHED_TIMESTAMP IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, DISPATCHED_TIMESTAMP) END) AS O2M_SAPL_WH1, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH2\' AND ORDER_TIMESTAMP IS NOT NULL AND DISPATCHED_TIMESTAMP IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, DISPATCHED_TIMESTAMP) END) AS O2M_SAPL_WH2, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-NORTH-TAURU\' AND ORDER_TIMESTAMP IS NOT NULL AND DISPATCHED_TIMESTAMP IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, DISPATCHED_TIMESTAMP) END) AS O2M_SAPL_NORTH_TAURU, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND ORDER_TIMESTAMP IS NOT NULL AND PACKED_TIME IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, PACKED_TIME) END) AS O2P_OVERALL, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH1\' AND ORDER_TIMESTAMP IS NOT NULL AND PACKED_TIME IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, PACKED_TIME) END) AS O2P_SAPL_WH1, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH2\' AND ORDER_TIMESTAMP IS NOT NULL AND PACKED_TIME IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, PACKED_TIME) END) AS O2P_SAPL_WH2, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-NORTH-TAURU\' AND ORDER_TIMESTAMP IS NOT NULL AND PACKED_TIME IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, PACKED_TIME) END) AS O2P_SAPL_NORTH_TAURU, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH1\' AND SLA_STATUS = \'WITHIN SLA\' THEN SALEORDERITEMCODE END ) AS SLA_SF_NUM_SAPL_WH1, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH1\' AND SLA_STATUS <> \'CANCELLED\' THEN SALEORDERITEMCODE END ) AS SLA_SF_DEN_SAPL_WH1, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH2\' AND SLA_STATUS = \'WITHIN SLA\' THEN SALEORDERITEMCODE END ) AS SLA_SF_NUM_SAPL_WH2, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH2\' AND SLA_STATUS <> \'CANCELLED\' THEN SALEORDERITEMCODE END ) AS SLA_SF_DEN_SAPL_WH2, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-NORTH-TAURU\' AND SLA_STATUS = \'WITHIN SLA\' THEN SALEORDERITEMCODE END ) AS SLA_SF_NUM_SAPL_NORTH_TAURU, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-NORTH-TAURU\' AND SLA_STATUS <> \'CANCELLED\' THEN SALEORDERITEMCODE END ) AS SLA_SF_DEN_SAPL_NORTH_TAURU FROM base GROUP BY REPORT_DATE ) SELECT REPORT_DATE, FORWARD_ITEMS, ROUND((FULFILL_NUM / NULLIF(FULFILL_DEN,0)) * 100, 2) AS FULFILLMENT_PCT, ROUND((SLA_SF_NUM / NULLIF(SLA_SF_DEN,0)) * 100, 2) AS SLA_ADHERENCE_SF_PCT, ROUND((SLA_MP_NUM / NULLIF(SLA_MP_DEN,0)) * 100, 2) AS SLA_ADHERENCE_MP_PCT, ROUND(O2M_OVERALL, 2) AS O2M_OVERALL, ROUND(O2M_SAPL_WH1, 2) AS O2M_SAPL_WH1, ROUND(O2M_SAPL_WH2, 2) AS O2M_SAPL_WH2, ROUND(O2M_SAPL_NORTH_TAURU, 2) AS O2M_SAPL_NORTH_TAURU, ROUND(O2P_OVERALL, 2) AS O2P_OVERALL, ROUND(O2P_SAPL_WH1, 2) AS O2P_SAPL_WH1, ROUND(O2P_SAPL_WH2, 2) AS O2P_SAPL_WH2, ROUND(O2P_SAPL_NORTH_TAURU, 2) AS O2P_SAPL_NORTH_TAURU, ROUND((SLA_SF_NUM_SAPL_WH1 / NULLIF(SLA_SF_DEN_SAPL_WH1,0)) * 100, 2) AS SLA_ADHERENCE_SF_SAPL_WH1_PCT, ROUND((SLA_SF_NUM_SAPL_WH2 / NULLIF(SLA_SF_DEN_SAPL_WH2,0)) * 100, 2) AS SLA_ADHERENCE_SF_SAPL_WH2_PCT, ROUND((SLA_SF_NUM_SAPL_NORTH_TAURU / NULLIF(SLA_SF_DEN_SAPL_NORTH_TAURU,0)) * 100, 2) AS SLA_ADHERENCE_SF_SAPL_NORTH_TAURU_PCT FROM daily ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            